/* From Uiverse.io by NlghtM4re - Tags: radio */
.__UIV_SCOPE__ .radio-buttons {
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: rgb(164, 215, 246);
  border-radius: 15px;
  box-shadow: rgb(71, 175, 239) 0px 5px 29px 5px;
}

.__UIV_SCOPE__ .radio-buttons label {
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .radio-buttons input[type="radio"] {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

.__UIV_SCOPE__ .option {
  position: relative;
  display: inline-block;
  padding-top: 10px;
  padding-bottom: 10px;
  border: none;
  color: black;
  border-radius: 14px;
  padding: 10px;
}

.__UIV_SCOPE__ .option:hover {
  background-color: rgb(137, 207, 251);
}

.__UIV_SCOPE__ .radio-buttons input[type="radio"]:checked + .option {
  background-color: rgb(71, 175, 239);
  box-shadow: rgb(11, 70, 107) 0px 5px 29px 5px;
}
